import functools

def semver_sort(versions):
    def parse(v):
        # remove build metadata
        main_part = v.split('+', 1)[0]
        if '-' in main_part:
            core, pre = main_part.split('-', 1)
        else:
            core, pre = main_part, None
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_identifier(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai < bi: return -1
            if ai > bi: return 1
            return 0
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        # both non-numeric, ASCII compare
        if a < b: return -1
        if a > b: return 1
        return 0

    def compare(v1, v2):
        maj1, min1, pat1, pre1 = parse(v1)
        maj2, min2, pat2, pre2 = parse(v2)
        t1 = (maj1, min1, pat1)
        t2 = (maj2, min2, pat2)
        if t1 < t2:
            return -1
        if t1 > t2:
            return 1
        # main versions equal
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None and pre2 is not None:
            return 1
        if pre1 is not None and pre2 is None:
            return -1
        # both have prerelease
        for a, b in zip(pre1, pre2):
            c = cmp_identifier(a, b)
            if c != 0:
                return c
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1
        return 0

    return sorted(versions, key=functools.cmp_to_key(compare))

